import re

_UNITS = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}


def parse_duration(text: str) -> int:
    if not re.fullmatch(r'(\d+[dhms])+', text):
        raise ValueError(text)
    return sum(int(n) * _UNITS[u] for n, u in re.findall(r'(\d+)([dhms])', text))

